def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edges.append((u, v, w, i + 1))
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    def bfs(start, excluded_edges):
        visited = set([start])
        queue = [start]
        head = 0
        while head < len(queue):
            curr = queue[head]
            head += 1
            for neighbor, edge_idx in adj[curr]:
                if neighbor not in visited and edge_idx not in excluded_edges:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    if neighbor == t:
                        return True
        return False

    # Check if already disconnected (0 cuts needed)
    if not bfs(s, set()):
        return "0\n0"

    best_cost = float('inf')
    best_edges_list = []

    # Try 1 cut (removing one edge)
    for i in range(m):
        cost = edges[i][2]
        excluded = {edges[i][3]}
        if not bfs(s, excluded):
            if cost < best_cost:
                best_cost = cost
                best_edges_list = [edges[i][3]]

    # Try 2 cuts (removing two edges)
    for i in range(m):
        for j in range(i + 1, m):
            cost = edges[i][2] + edges[j][2]
            excluded = {edges[i][3], edges[j][3]}
            if not bfs(s, excluded):
                if cost < best_cost:
                    best_cost = cost
                    best_edges_list = [edges[i][3], edges[j][3]]

    if best_cost == float('inf'):
        return "-1"

    return f"{best_cost}\n{len(best_edges_list)}\n{' '.join(map(str, best_edges_list))}"

