    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    lucky_numbers = set()
    def generate_lucky(current, max_n):
        if current > max_n:
            return
        if current <= max_n:
            lucky_numbers.add(current)
        if current * 10 + 4 > max_n and current * 10 + 7 > max_n:
            return
        generate_lucky(current * 10 + 4, max_n)
        generate_lucky(current * 10 + 7, max_n)

    generate_lucky(0, n)

    lucky_numbers.discard(0)

    min_roads = float('inf')

    component_count = len(component_sizes)

    if component_count == 1:
        if component_sizes[0] in lucky_numbers:
            return "0\n"
        else:
            min_roads = 1
    else:
        for size in component_sizes:
            if size in lucky_numbers:
                return "0\n"

        for target in sorted(lucky_numbers):
            if target > n:
                continue

            min_roads = min(min_roads, component_count)

        if min_roads == float('inf'):
