    return f"{min_roads}\n" if min_roads != float('inf') else "-1\n"

def solution(input_str):
    # Split input into lines
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Extract grid rows (skip the first line with dimensions)
    grid_lines = [lines[i] for i in range(1, n + 1)]

    # For each column, find the minimum and maximum row where there's a '.'
    col_min = [None] * m
    col_max = [-1] * m

    for i in range(n):
        line = grid_lines[i]
        for j in range(m):
            # Handle edge case where row length might be less than m
            if j < len(line) and line[j] == '.':
                if col_min[j] is None:
                    col_min[j] = i
                    col_max[j] = i
                elif i > col_max[j]:
                    col_max[j] = i

    # Reconstruct grid: keep '.' in spanning ranges, otherwise use '*'
    result = []
    for i in range(n):
        row = []
        for j in range(m):
            # Fill '.' in column j from min to max row found
            if col_min[j] is not None and col_min[j] <= i <= col_max[j]:
                row.append('.')
            else:
                row.append('*')
        result.append(''.join(row))

    return '\n'.join(result)

