# Solution
def solution(input_text):
    MOD = 1000000000

    lines = input_text.strip().split('\n')
    if not lines:
        return ""

    parts = lines[0].split()
    n = int(parts[0])
    m = int(parts[1])

    a = list(map(int, lines[1].split()))

    # Precompute fibonacci weights: f0=1, f1=1, f2=2, f3=3, f4=5, ...
    fib = [0] * (n + 1)
    if n >= 0:
        fib[0] = 1
    if n >= 1:
        fib[1] = 1
    for i in range(2, n + 1):
        fib[i] = (fib[i - 1] + fib[i - 2]) % MOD

    # Build base tree with weighted values
    tree_size = 1
    while tree_size < n:
        tree_size *= 2

    tree = [0] * (4 * tree_size)
    lazy = [0] * (2 * tree_size)

    def _build(idx, l, r):
        if l == r:
            tree[idx] = (a[l - 1] * fib[l]) % MOD
            return
        mid = (l + r) >> 1
        _build(idx << 1, l, mid)
        _build((idx << 1) + 1, mid + 1, r)
        tree[idx] = (tree[idx << 1] + tree[(idx << 1) + 1]) % MOD

    _build(1, 1, n)

    def _push(idx):
        if lazy[idx] != 0:
            lazy[idx << 1] += lazy[idx]
            lazy[(idx << 1) + 1] += lazy[idx]
            lazy[idx] = 0

    def point_set(node, l, r, pos, val):
        if l == r:
            tree[node] = val % MOD
            return
        _push(node)
        mid = (l + r) >> 1
        if pos <= mid:
            point_set(node << 1, l, mid, pos, val)
        else:
            point_set((node << 1) + 1, mid + 1, r, pos, val)
        tree[node] = (tree[node << 1] + tree[(node << 1) + 1]) % MOD

    def range_add(node, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            lazy[node] += val
            return
        _push(node)
        mid = (l + r) >> 1
        if ql <= mid:
            range_add(node << 1, l, mid, ql, qr, val)
        if qr > mid:
            range_add((node << 1) + 1, mid + 1, r, ql, qr, val)
        tree[node] = (tree[node << 1] + tree[(node << 1) + 1]) % MOD

    results = []

    for i in range(2, len(lines)):
        parts = lines[i].split()
        t = int(parts[0])
        if t == 1:
            x = int(parts[1])
            v = int(parts[2])
            point_set(1, 1, n, x, v)
        elif t == 2:
            l = int(parts[1])
            r = int(parts[2])
            results.append(str(query_sum(1, 1, n, l, r)))
        elif t == 3:
            l = int(parts[1])
            r = int(parts[2])
            d = int(parts[3])
            range_add(1, 1, n, l, r, d)

    return '\n'.join(results)

def query_sum(node, l, r, ql, qr):
    if ql <= l and r <= qr:
        return tree[node] % MOD
    _push(node)
    mid = (l + r) >> 1
    res = 0
    if ql <= mid:
        res += query_sum(node << 1, l, mid, ql, qr)
    if qr > mid:
        res += query_sum((node << 1) + 1, mid + 1, r, ql, qr)
    return res % MOD

