    if current:
        segments.append(current)

    friends = set()
    for seg in segments:
        friends.update(seg)
    friends = sorted(list(friends))
    friend_to_idx = {f: i for i, f in enumerate(friends)}
    n_friends = len(friends)

    if n_friends == 0:
        return "0"

    conflict = [[False] * n_friends for _ in range(n_friends)]
    for seg in segments:
        ss = list(seg)
        for i in range(len(ss)):
            for j in range(i + 1, len(ss)):
                u, v = friend_to_idx[ss[i]], friend_to_idx[ss[j]]
                conflict[u][v] = conflict[v][u] = True

    # Efficient MIS using bit manipulation and recursion
    result = [0]

    def solve(idx, mask, count):
        if idx == n_friends:
            result[0] = max(result[0], count)
            return
        if count + (n_friends - idx) <= result[0]:
            return

        if count >= result[0]:
            result[0] = count
            return

        can_include = True
        for j in range(idx):
            if (mask >> j) & 1 and conflict[idx][j]:
                can_include = False
                break

        if can_include:
            solve(idx + 1, mask | (1 << idx), count + 1)
        solve(idx + 1, mask, count)

    solve(0, 0, 0)
    return str(result[0])

