    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    frogs = []
    pos_list = []

    for i in range(n):
        pi, ai = map(int, lines[1 + i].split())
        frogs.append({'id': i + 1, 'pos': pi, 'jump': ai, 'active': True})
        pos_list.append(pi)

    # Track positions using sorted list
    sorted_frogs = [(frogs[i]['pos'], frogs[i]['id'], frogs[i]) for i in range(n)]
    sorted_frogs.sort()

    # Active set
    active = set(range(n))

    # Map position to the set of frog indices
    pos_to_active = {}
    for i in range(n):
        if i in active:
            pos_to_active.setdefault(frogs[i]['pos'], set()).add(i)

    turn = 0

    while True:
        # Check if any active frogs remain
        if not active:
            break

        # Find next active frog in turn order
        start_pos = (turn % n)

        # Find the first active frog starting from turn
        found = False
        for _ in range(n):
            idx = (start_pos + _) % n
            if idx in active:
                current_frog = frogs[idx]
                found = True
                break

        if not found:
            break

        old_pos = current_frog['pos']
        dest_pos = (old_pos + current_frog['jump'] - 1) % m + 1

        # Collect frogs on the path
        knocked_out_indices = set()

        # Path is from old_pos+1 to dest_pos (cyclic)
        if dest_pos <= old_pos:
            # Wrap around: [old_pos+1, m] and [1, dest_pos]
            # First part
            for pos in range(old_pos + 1, m + 1):
                if pos in pos_to_active:
                    for fid in pos_to_active[pos]:
                        if fid in active and fid != idx:
                            knocked_out_indices.add(fid)
            # Second part  
            for pos in range(1, dest_pos + 1):
                if pos in pos_to_active:
                    for fid in pos_to_active[pos]:
                        if fid in active and fid != idx:
                            knocked_out_indices.add(fid)
        else:
            # Normal: [old_pos+1, dest_pos]
            for pos in range(old_pos + 1, dest_pos + 1):
                if pos in pos_to_active:
                    for fid in pos_to_active[pos]:
                        if fid in active and fid != idx:
                            knocked_out_indices.add(fid)

        # Remove knocked out frogs
        for fid in knocked_out_indices:
            active.remove(fid)
            del frogs[fid]['pos']  # Don't touch deleted

        # Update current frog's jump
        current_frog['jump'] -= len(knocked_out_indices)

        # Current frog also moves to destination (unless knocked out)
        if idx in active:
            current_frog['pos'] = dest_pos
            pos_to_active[old_pos] = None  # Old position cleared
            pos_to_active[dest_pos] = pos_to_active.get(dest_pos, set())
            pos_to_active[dest_pos].add(idx)

    # Get remaining frogs
    result_ids = sorted([frogs[i]['id'] for i in active])

    if not result_ids:
        return '0\n'

    ans = '\n'.join([str(len(result_ids)), ' '.join(map(str, result_ids))])
    return ans + '\n' if result_ids else '0\n'

