def solution(input_str):
    n, k = map(int, input_str.strip().split())

    def bit_reverse(x, n):
        result = 0
        for i in range(n):
            result |= ((x >> i) & 1) << (n - 1 - i)
        return result

    def bit_flip(x, n):
        return (~x) & ((1 << n) - 1)

    seen = set()
    representatives = []

    for mask in range(1 << n):
        if mask in seen:
            continue

        # Build the equivalence class
        group = set()
        group.add(mask)

        # Generate all equivalent
        queue = [mask]
        while queue:
            current = queue.pop(0)
            op1 = bit_reverse(current, n)
            if op1 not in group:
                group.add(op1)
            if op1 not in seen:
                seen.add(op1)

            op2 = bit_flip(current, n)
            if op2 not in group:
                group.add(op2)
                seen.add(op2)
            if op2 not in seen:
                seen.add(op2)

            op3 = bit_reverse(op2, n)
            if op3 not in group:
                group.add(op3)
                seen.add(op3)

        representatives.append(min(group))

    representatives.sort()

    if k > len(representatives):
        return "-1"

    return "{:0{}b}".format(representatives[k-1], n)
